using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using ShouTech.App.Interaction;
using ShouTech.App.Services;
using ShouTech.Application.Services;
using ShouTech.Domain.Entities;

namespace ShouTech.App.Views;

/// <summary>
/// Installments window (ribbon completion F1): creates installment plans
/// whose schedule is generated by <see cref="DefinitionService.BuildSchedule"/>
/// (equal monthly amounts, remainder on the last row) and persisted with the
/// plan in ONE transaction. Collecting a schedule row records the payment and
/// posts the party_ledger credit in the same transaction (repository).
/// The filter bar (party / status) is the search mode that also serves the
/// SearchInstallment ribbon entry. Actions live in the bottom command bar.
/// </summary>
public sealed class InstallmentsWin : BaseWin
{
    private readonly DefinitionService? _service;
    private readonly List<InstallmentPlan> _plans = new();
    private readonly List<InstallmentScheduleRow> _schedule = new();
    private readonly List<(TextBlock Label, string Key)> _labels = new();
    private readonly List<(DataGridColumn Column, string Key)> _headers = new();

    private readonly DataGrid _grid = new();
    private readonly DataGrid _scheduleGrid = new();
    private readonly TextBox _filterParty = new();
    private readonly ComboBox _filterStatus = new();
    private readonly TextBox _party = new();
    private readonly TextBox _docRef = new();
    private readonly TextBox _total = new();
    private readonly TextBox _downPayment = new();
    private readonly TextBox _count = new();
    private readonly DatePicker _startDate = new();
    private readonly TextBox _notes = new();
    private readonly TextBox _collectAmount = new();
    private readonly DatePicker _collectDate = new();
    private readonly TextBlock _plansHeader = new();
    private readonly TextBlock _scheduleHeader = new();
    private readonly TextBlock _statusBar = new();
    private readonly Button _searchButton = new();
    private readonly Button _newButton = new();
    private readonly Button _createButton = new();
    private readonly Button _deleteButton = new();
    private readonly Button _collectButton = new();
    private readonly Button _refreshButton = new();
    private readonly Button _closeButton = new();

    private string? _selectedPlanId;
    private string? _selectedScheduleId;

    public InstallmentsWin()
    {
        _service = AppHost.Definitions;
        Width = 1180;
        Height = 760;
        MinWidth = 660;
        MinHeight = 360;
        BuildUi();
        Loaded += OnLoaded;
    }

    private async void OnLoaded(object sender, RoutedEventArgs e)
    {
        if (!AppHost.Permissions.Has(PermCat.Vouchers.InstallmentView) && !AppHost.Permissions.Has(PermCat.Vouchers.InstallmentManage))
        {
            MessageBox.Show(this, T("Installments.PermissionDenied"), Title, MessageBoxButton.OK, MessageBoxImage.Warning);
            Close();
            return;
        }
        var canManage = AppHost.Permissions.Has(PermCat.Vouchers.InstallmentManage);
        _createButton.IsEnabled = canManage;
        _deleteButton.IsEnabled = canManage;
        _collectButton.IsEnabled = canManage;
        await RefreshAsync();
    }

    private void BuildUi()
    {
        var root = new DockPanel { Margin = new Thickness(12) };

        var statusBorder = new Border
        {
            Child = _statusBar,
            Padding = new Thickness(2, 5, 2, 0),
            BorderThickness = new Thickness(0, 1, 0, 0)
        };
        statusBorder.SetResourceReference(Border.BorderBrushProperty, "BorderBrush");
        DockPanel.SetDock(statusBorder, Dock.Bottom);
        root.Children.Add(statusBorder);

        var bar = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
        StyleButton(_newButton, "Common.New");
        StyleButton(_createButton, "Installments.CreatePlan");
        StyleButton(_deleteButton, "Common.Delete");
        StyleButton(_collectButton, "Installments.Collect");
        StyleButton(_refreshButton, "Common.Refresh");
        StyleButton(_closeButton, "Common.Close");
        _newButton.Click += (_, _) => ClearEditor();
        _createButton.Click += async (_, _) => await CreateAsync();
        _deleteButton.Click += async (_, _) => await DeleteAsync();
        _collectButton.Click += async (_, _) => await CollectAsync();
        _refreshButton.Click += async (_, _) => await RefreshAsync();
        _closeButton.Click += (_, _) => Close();
        foreach (var b in new[] { _newButton, _createButton, _deleteButton, _collectButton, _refreshButton, _closeButton })
            bar.Children.Add(b);
        var barBorder = new Border
        {
            Child = bar,
            Padding = new Thickness(4),
            Margin = new Thickness(0, 8, 0, 0),
            BorderThickness = new Thickness(0, 1, 0, 0)
        };
        barBorder.SetResourceReference(Border.BorderBrushProperty, "BorderBrush");
        DockPanel.SetDock(barBorder, Dock.Bottom);
        root.Children.Add(barBorder);

        // Search bar (search mode for the SearchInstallment ribbon entry):
        // a 2-pair form grid + the search button docked beside its row.
        var searchForm = CreateFormGrid(2);
        AddFormField(_labels, searchForm, 0, 0, "Installments.PartyCode", _filterParty);
        AddFormField(_labels, searchForm, 0, 1, "Installments.Status", _filterStatus);
        _filterStatus.ItemsSource = new[] { string.Empty }.Concat(InstallmentStatuses.All).ToList();
        _filterStatus.SelectedIndex = 0;
        StyleButton(_searchButton, "Installments.Search");
        _searchButton.Margin = new Thickness(8, 0, 0, 0);
        _searchButton.VerticalAlignment = VerticalAlignment.Top;
        _searchButton.Click += async (_, _) => await RefreshAsync();
        var searchBar = new DockPanel { Margin = new Thickness(0, 0, 0, 8) };
        DockPanel.SetDock(_searchButton, Dock.Right);
        searchBar.Children.Add(_searchButton);
        searchBar.Children.Add(searchForm);
        DockPanel.SetDock(searchBar, Dock.Top);
        root.Children.Add(searchBar);

        var content = new Grid();
        content.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        content.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        content.RowDefinitions.Add(new RowDefinition { Height = new GridLength(180) });
        content.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        content.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(330) });

        var listPanel = new DockPanel { Margin = new Thickness(0, 0, 12, 0) };
        _plansHeader.FontWeight = FontWeights.SemiBold;
        _plansHeader.Margin = new Thickness(0, 0, 0, 6);
        DockPanel.SetDock(_plansHeader, Dock.Top);
        listPanel.Children.Add(_plansHeader);
        ConfigureGrid(_grid);
        _grid.Columns.Add(TextCol("Installments.PartyCode", nameof(InstallmentPlan.PartyCode), 110));
        _grid.Columns.Add(TextCol("Installments.DocRef", nameof(InstallmentPlan.DocRef), 110));
        _grid.Columns.Add(TextCol("Installments.Total", nameof(InstallmentPlan.TotalAmount), 110, numeric: true));
        _grid.Columns.Add(TextCol("Installments.DownPayment", nameof(InstallmentPlan.DownPayment), 110, numeric: true));
        _grid.Columns.Add(TextCol("Installments.Count", nameof(InstallmentPlan.InstallmentCount), 70, center: true));
        _grid.Columns.Add(TextCol("Installments.StartDate", nameof(InstallmentPlan.StartDate), 95, center: true));
        _grid.Columns.Add(TextCol("Installments.Status", nameof(InstallmentPlan.Status), 90));
        _grid.Columns.Add(TextCol("Installments.Remaining", nameof(InstallmentPlan.Remaining), 110, numeric: true));
        _grid.SelectionChanged += async (_, _) => await OnPlanSelectedAsync();
        listPanel.Children.Add(_grid);
        Grid.SetRow(listPanel, 0);
        Grid.SetColumn(listPanel, 0);
        content.Children.Add(listPanel);

        // Editor = a one-pair form grid: side labels, aligned edges
        // down the whole editor (Phenix rule).
        var editor = CreateFormGrid(1);
        AddFormField(_labels, editor, 0, 0, "Installments.PartyCode", _party);
        AddFormField(_labels, editor, 1, 0, "Installments.DocRef", _docRef);
        AddFormField(_labels, editor, 2, 0, "Installments.Total", _total);
        AddFormField(_labels, editor, 3, 0, "Installments.DownPayment", _downPayment);
        AddFormField(_labels, editor, 4, 0, "Installments.Count", _count);
        AddFormField(_labels, editor, 5, 0, "Installments.StartDate", _startDate);
        AddFormField(_labels, editor, 6, 0, "Installments.Notes", _notes);
        _startDate.SelectedDate = DateTime.Today;
        var editorScroll = new ScrollViewer { Content = editor, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
        Grid.SetRow(editorScroll, 0);
        Grid.SetColumn(editorScroll, 1);
        content.Children.Add(editorScroll);

        _scheduleHeader.FontWeight = FontWeights.SemiBold;
        _scheduleHeader.Margin = new Thickness(0, 10, 0, 6);
        Grid.SetRow(_scheduleHeader, 1);
        Grid.SetColumnSpan(_scheduleHeader, 2);
        content.Children.Add(_scheduleHeader);

        var schedulePanel = new Grid();
        schedulePanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        schedulePanel.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(330) });
        ConfigureGrid(_scheduleGrid);
        _scheduleGrid.Columns.Add(TextCol("Installments.Seq", nameof(InstallmentScheduleRow.Seq), 60, center: true));
        _scheduleGrid.Columns.Add(TextCol("Installments.DueDate", nameof(InstallmentScheduleRow.DueDate), 100, center: true));
        _scheduleGrid.Columns.Add(TextCol("Installments.Amount", nameof(InstallmentScheduleRow.Amount), 110, numeric: true));
        _scheduleGrid.Columns.Add(TextCol("Installments.PaidAmount", nameof(InstallmentScheduleRow.PaidAmount), 110, numeric: true));
        _scheduleGrid.Columns.Add(TextCol("Installments.PaidDate", nameof(InstallmentScheduleRow.PaidDate), 100, center: true));
        _scheduleGrid.Columns.Add(TextCol("Installments.Status", nameof(InstallmentScheduleRow.Status), 90));
        _scheduleGrid.Columns.Add(TextCol("Installments.Remaining", nameof(InstallmentScheduleRow.Remaining), 110, numeric: true));
        _scheduleGrid.SelectionChanged += (_, _) => OnScheduleSelected();
        var scheduleHost = new DockPanel { Margin = new Thickness(0, 0, 12, 0) };
        scheduleHost.Children.Add(_scheduleGrid);
        Grid.SetColumn(scheduleHost, 0);
        schedulePanel.Children.Add(scheduleHost);
        var collectEditor = CreateFormGrid(1);
        AddFormField(_labels, collectEditor, 0, 0, "Installments.CollectAmount", _collectAmount);
        AddFormField(_labels, collectEditor, 1, 0, "Installments.PaidDate", _collectDate);
        _collectDate.SelectedDate = DateTime.Today;
        Grid.SetColumn(collectEditor, 1);
        schedulePanel.Children.Add(collectEditor);
        Grid.SetRow(schedulePanel, 2);
        Grid.SetColumnSpan(schedulePanel, 2);
        content.Children.Add(schedulePanel);

        root.Children.Add(content);
        Content = root;
        ApplyLocalizedText();
    }

    protected override void ApplyLocalizedText()
    {
        Title = T("Installments.Title");
        _plansHeader.Text = T("Installments.Title");
        _scheduleHeader.Text = T("Installments.Schedule");
        foreach (var (label, key) in _labels)
            label.Text = T(key);
        foreach (var (column, key) in _headers)
            column.Header = T(key);
        foreach (var b in new[] { _searchButton, _newButton, _createButton, _deleteButton, _collectButton, _refreshButton, _closeButton })
            if (b.Tag is string key)
                b.Content = T(key);
        UpdateStatusBar();
    }

    private async Task RefreshAsync()
    {
        try
        {
            if (_service is null)
            {
                _statusBar.Text = T("Installments.ServiceUnavailable");
                return;
            }
            var status = _filterStatus.SelectedItem as string;
            var rows = await _service.ListInstallmentsAsync(
                CurrentCompanyCode,
                string.IsNullOrWhiteSpace(_filterParty.Text) ? null : _filterParty.Text.Trim(),
                string.IsNullOrWhiteSpace(status) ? null : status);
            _plans.Clear();
            _plans.AddRange(rows);
            _grid.ItemsSource = null;
            _grid.ItemsSource = _plans;
            UpdateStatusBar();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, Title, MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private async Task OnPlanSelectedAsync()
    {
        if (_grid.SelectedItem is not InstallmentPlan plan)
            return;
        _selectedPlanId = plan.Id;
        _party.Text = plan.PartyCode;
        _docRef.Text = plan.DocRef ?? string.Empty;
        _total.Text = plan.TotalAmount.ToString("0.##", CultureInfo.CurrentCulture);
        _downPayment.Text = plan.DownPayment.ToString("0.##", CultureInfo.CurrentCulture);
        _count.Text = plan.InstallmentCount.ToString(CultureInfo.InvariantCulture);
        _startDate.SelectedDate = plan.StartDate.ToDateTime(TimeOnly.MinValue);
        _notes.Text = plan.Notes ?? string.Empty;
        await LoadScheduleAsync();
    }

    private async Task LoadScheduleAsync()
    {
        _schedule.Clear();
        _scheduleGrid.ItemsSource = null;
        _selectedScheduleId = null;
        if (_service is null || _selectedPlanId is null)
            return;
        try
        {
            var rows = await _service.ListScheduleAsync(CurrentCompanyCode, _selectedPlanId);
            _schedule.AddRange(rows);
            _scheduleGrid.ItemsSource = _schedule;
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, Title, MessageBoxButton.OK, MessageBoxImage.Error);
        }
        UpdateStatusBar();
    }

    private void OnScheduleSelected()
    {
        if (_scheduleGrid.SelectedItem is not InstallmentScheduleRow row)
            return;
        _selectedScheduleId = row.Id;
        _collectAmount.Text = row.Remaining.ToString("0.##", CultureInfo.CurrentCulture);
    }

    private async Task CreateAsync()
    {
        try
        {
            if (_service is null)
                throw new InvalidOperationException(T("Installments.ServiceUnavailable"));
            if (!AppHost.Permissions.Has(PermCat.Vouchers.InstallmentManage))
                throw new InvalidOperationException(T("Installments.PermissionDenied"));
            var plan = new InstallmentPlan
            {
                PartyCode = _party.Text.Trim(),
                DocRef = NullIfBlank(_docRef.Text),
                TotalAmount = ParseDecimal(_total.Text, "Installments.Total"),
                DownPayment = ParseDecimal(_downPayment.Text, "Installments.DownPayment"),
                InstallmentCount = ParseInt(_count.Text),
                StartDate = _startDate.SelectedDate.HasValue
                    ? DateOnly.FromDateTime(_startDate.SelectedDate.Value)
                    : DateOnly.FromDateTime(DateTime.Today),
                Notes = NullIfBlank(_notes.Text),
                Status = InstallmentStatuses.Active
            };
            var id = await _service.CreateInstallmentAsync(CurrentCompanyCode, plan, CurrentUserId);
            _selectedPlanId = id;
            MessageBox.Show(this, T("Installments.Created"), Title, MessageBoxButton.OK, MessageBoxImage.Information);
            await RefreshAsync();
            await LoadScheduleAsync();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, Title, MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private async Task DeleteAsync()
    {
        try
        {
            if (_service is null || _selectedPlanId is null)
                return;
            if (!AppHost.Permissions.Has(PermCat.Vouchers.InstallmentManage))
                throw new InvalidOperationException(T("Installments.PermissionDenied"));
            if (MessageBox.Show(this, T("Common.ConfirmDelete"), Title, MessageBoxButton.YesNo, MessageBoxImage.Warning) != MessageBoxResult.Yes)
                return;
            await _service.DeleteInstallmentAsync(CurrentCompanyCode, _selectedPlanId, CurrentUserId);
            _selectedPlanId = null;
            ClearEditor();
            await RefreshAsync();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, Title, MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private async Task CollectAsync()
    {
        try
        {
            if (_service is null || _selectedScheduleId is null)
                return;
            if (!AppHost.Permissions.Has(PermCat.Vouchers.InstallmentManage))
                throw new InvalidOperationException(T("Installments.PermissionDenied"));
            var amount = ParseDecimal(_collectAmount.Text, "Installments.CollectAmount");
            var paidDate = _collectDate.SelectedDate.HasValue
                ? DateOnly.FromDateTime(_collectDate.SelectedDate.Value)
                : DateOnly.FromDateTime(DateTime.Today);
            var updated = await _service.CollectInstallmentAsync(CurrentCompanyCode, _selectedScheduleId, amount, paidDate, CurrentUserId);
            MessageBox.Show(this, $"{T("Installments.Collected")} · {updated.PaidAmount:0.##} / {updated.Amount:0.##} · {updated.Status}", Title, MessageBoxButton.OK, MessageBoxImage.Information);
            await RefreshAsync();
            await LoadScheduleAsync();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, Title, MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private void ClearEditor()
    {
        _selectedPlanId = null;
        _selectedScheduleId = null;
        _grid.SelectedItem = null;
        _party.Clear();
        _docRef.Clear();
        _total.Clear();
        _downPayment.Clear();
        _count.Clear();
        _startDate.SelectedDate = DateTime.Today;
        _notes.Clear();
        _schedule.Clear();
        _scheduleGrid.ItemsSource = null;
        UpdateStatusBar();
    }

    private void UpdateStatusBar()
    {
        var remaining = _plans.Sum(p => p.Remaining);
        _statusBar.Text = $"{_plans.Count} · {T("Installments.Remaining")}: {remaining:N2} · {_schedule.Count} {T("Installments.Schedule")}";
    }

    private static void ConfigureGrid(DataGrid grid)
    {
        grid.AutoGenerateColumns = false;
        grid.CanUserAddRows = false;
        grid.CanUserDeleteRows = false;
        grid.IsReadOnly = true;
        grid.CanUserSortColumns = true;
        grid.CanUserReorderColumns = true;
        grid.CanUserResizeColumns = true;
        grid.SelectionMode = DataGridSelectionMode.Single;
        grid.SelectionUnit = DataGridSelectionUnit.FullRow;
        grid.RowHeaderWidth = 0;
        grid.GridLinesVisibility = DataGridGridLinesVisibility.Horizontal;
        grid.AlternationCount = 2;
        DataGridTableBehavior.SetEnableStandardContextMenu(grid, true);
    }

    private DataGridTextColumn TextCol(string key, string path, double width, bool numeric = false, bool center = false)
    {
        var column = new DataGridTextColumn
        {
            Binding = new Binding(path),
            Width = new DataGridLength(width)
        };
        if (numeric)
            column.ElementStyle = RightAlignStyle;
        else if (center)
            column.ElementStyle = CenterAlignStyle;
        _headers.Add((column, key));
        return column;
    }

    private static readonly Style RightAlignStyle = new(typeof(TextBlock))
    {
        Setters = { new Setter(TextBlock.TextAlignmentProperty, TextAlignment.Right) }
    };

    private static readonly Style CenterAlignStyle = new(typeof(TextBlock))
    {
        Setters = { new Setter(TextBlock.TextAlignmentProperty, TextAlignment.Center) }
    };


    private static void StyleButton(Button button, string key)
    {
        button.Tag = key;
        button.MinWidth = VisuId.ButtonMinWidth;
        button.MinHeight = VisuId.ControlHeight;
        button.Margin = new Thickness(8, 0, 0, 0);
        button.Padding = new Thickness(14, 0, 14, 0);
    }

    private static string? NullIfBlank(string? value)
        => string.IsNullOrWhiteSpace(value) ? null : value.Trim();

    private static decimal ParseDecimal(string text, string fieldKey)
    {
        if (string.IsNullOrWhiteSpace(text))
            return 0m;
        if (decimal.TryParse(text.Trim(), NumberStyles.Number, CultureInfo.CurrentCulture, out var v) ||
            decimal.TryParse(text.Trim(), NumberStyles.Number, CultureInfo.InvariantCulture, out v))
            return v;
        throw new InvalidOperationException($"Invalid number: {fieldKey}.");
    }

    private static int ParseInt(string text)
    {
        if (int.TryParse(text.Trim(), NumberStyles.Integer, CultureInfo.CurrentCulture, out var v) ||
            int.TryParse(text.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out v))
            return v;
        throw new InvalidOperationException("Installment count must be a whole number.");
    }
}
